        oChon('scn-lop', ds.map(function (l) { return [l.lop, 'Lớp ' + l.lop + (D.gvcnCua[chuanLop(l.lop)] ? ' · ' + D.gvcnCua[chuanLop(l.lop)] : '')]; }), D.lop) + '</div>';
